begin;
create type public.kpi_scope as enum('PROGRAM','PROJECT','INTERN');create type public.kpi_cadence as enum('WEEKLY','MONTHLY','QUARTERLY','CUSTOM');create type public.kpi_direction as enum('HIGHER_BETTER','LOWER_BETTER');create type public.kpi_status as enum('ACTIVE','ARCHIVED');create type public.kpi_achievement_status as enum('ON_TRACK','OFF_TRACK','NO_TARGET');
create table public.kpi_definitions(id uuid primary key default gen_random_uuid(),name text not null,description text not null default '',scope public.kpi_scope not null,program_id uuid references public.programs(id) on delete restrict,project_id uuid references public.projects(id) on delete restrict,intern_id uuid references public.interns(id) on delete restrict,unit text not null,target_value numeric,direction public.kpi_direction not null default 'HIGHER_BETTER',cadence public.kpi_cadence not null default 'MONTHLY',status public.kpi_status not null default 'ACTIVE',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.profiles(id) on delete set null,updated_by uuid references public.profiles(id) on delete set null,constraint kpi_name_blank check(length(trim(name))>0),constraint kpi_unit_blank check(length(trim(unit))>0),constraint kpi_scope_target check((scope='PROGRAM' and program_id is not null and project_id is null and intern_id is null)or(scope='PROJECT' and project_id is not null and program_id is null and intern_id is null)or(scope='INTERN' and intern_id is not null and program_id is null and project_id is null)));
create table public.kpi_results(id uuid primary key default gen_random_uuid(),kpi_definition_id uuid not null references public.kpi_definitions(id) on delete restrict,period_start date not null,period_end date not null,value numeric not null,achievement_status public.kpi_achievement_status not null default 'NO_TARGET',notes text not null default '',recorded_at timestamptz not null default now(),recorded_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id) on delete set null,constraint kpi_period_order check(period_start<=period_end),constraint kpi_result_unique unique(kpi_definition_id,period_start,period_end));
create index idx_kpi_definitions_scope_status on public.kpi_definitions(scope,status);create index idx_kpi_results_timeline on public.kpi_results(kpi_definition_id,period_end desc);
create function public.calculate_kpi_achievement()returns trigger language plpgsql set search_path=public as $$declare t numeric;d public.kpi_direction;begin select target_value,direction into t,d from public.kpi_definitions where id=new.kpi_definition_id;if t is null then new.achievement_status='NO_TARGET';elsif(d='HIGHER_BETTER' and new.value>=t)or(d='LOWER_BETTER' and new.value<=t)then new.achievement_status='ON_TRACK';else new.achievement_status='OFF_TRACK';end if;return new;end;$$;
create trigger calculate_kpi_achievement before insert or update on public.kpi_results for each row execute procedure public.calculate_kpi_achievement();create trigger set_kpi_definitions_updated_at before update on public.kpi_definitions for each row execute procedure public.set_updated_at();create trigger set_kpi_results_updated_at before update on public.kpi_results for each row execute procedure public.set_updated_at();
grant select,insert,update on public.kpi_definitions,public.kpi_results to authenticated;alter table public.kpi_definitions enable row level security;alter table public.kpi_results enable row level security;create policy kpi_definitions_admin_all on public.kpi_definitions for all to authenticated using((select public.is_admin()))with check((select public.is_admin())and updated_by=(select auth.uid()));create policy kpi_results_admin_all on public.kpi_results for all to authenticated using((select public.is_admin()))with check((select public.is_admin())and updated_by=(select auth.uid()));
commit;
